"""Publish coupled numerical evidence and its physical applicability limits."""
import json
from .native_design_kernel import ROOT
from .study_open_sizing import validate


def publication():
    def read(name):
        r=json.loads((ROOT/'docs/analysis'/name).read_text());validate(r['sourceHashes']);return r
    search=read('coupled-sizing-search.json');replay=read('coupled-sizing-replay.json');recovery=read('coupled-recovery.json');pitch=read('coupled-pitch-diagnostic.json');wing=read('wing-candidate-check.json')
    expected={'nominal','construction','aerodynamic','hydrodynamic','energy','combined'}
    if {c['scenario'] for c in replay['scenarios']}!=expected:
        raise ValueError('All six sensitivity scenarios are required before publishing the authoritative report')
    contract=json.loads((ROOT/'.tools/coupled-operation-contract.json').read_text());validate(contract['sourceHashes'])
    def core_pass(r):
        return r['numericallyBalanced'] and r['minimumOperatingMargin']>=-1e-4 and min(r['structure'].values())>=-1e-4 and min(r['route'][:3])>=-1e-4 and min(r['westerlyRoute'][:3])>=-1e-4
    def roll_pass(r):
        return all(c['failedEquilibria']==0 and c['minimumInteriorRestoring_Nm'] is not None and c['minimumInteriorRestoring_Nm']>0 for c in r['recovery'])
    nominal=next(r for r in replay['scenarios'] if r['scenario']=='nominal')
    d=search['design'];length=d['length_m'];beam=d['beam_m'];hits=[]
    for i,(name,value) in enumerate(d.items()):
        lo,hi=contract['designLower'][i],contract['designUpper'][i]
        if value-lo<=1e-3*max(abs(value),abs(lo),1e-6):hits.append(f'{name}: lower bracket {lo:g}')
        if hi-value<=1e-3*max(abs(value),abs(hi),1e-6):hits.append(f'{name}: upper bracket {hi:g}')
    margin=lambda value:f'{0.0 if abs(value)<1e-4 else value:.3f}'
    lines=['# Coupled sizing results','','<!-- Generated by scripts.publish_coupled_results. -->','',
      '**Exploratory sizing result, not a selected or qualified boat.** The search uses a hull-form-dependent resistance regression and explicit applicability screens. Numerical feasibility remains conditional on the stated physical models and sensitivity replay.','',
      f"The shared-design solve returned (coarse screens pass: {search['coarseFeasible']}): **{length:.3f} m length by {beam:.3f} m beam**, {search['mass']['totalMass']:.2f} kg at the search mesh resolution. Its length/beam ratio is {length/beam:.2f}. The hull fullness exponent is free. Native Delft residuary resistance replaces the former displacement/Froude shortcut; the geometry and speed must pass its declared screening envelope. Bounds alone do not validate every hull inside that envelope.",'',
      f"Search geometry resolution: {search.get('geometryResolution',4)}. Optimizer stop: {search['optimizerMessage']}. Initial constrained feasibility fallback: {search.get('feasibilitySqpMessage') or 'not needed'}. Feasibility restoration: {search.get('feasibilityRestorationMessage') or 'not needed'}. Search maximum scaled equilibrium residual: {search['maxEquilibriumResidual']:.3g}; minimum normalized margin: {search['minimumMargin']:.3g}. Numerical convergence does not establish physical applicability.",'',
      f"Search-only energy reserve: {100*search['cycleEnergySearchReserve']:.2f} Wh/day. The progress search reserve is {search['progressSearchReserve_m_s']:.3f} m/s on each leg. These protect against numerical replay drift; adverse physical assumptions are assessed separately. SLSQP stopping tolerance: {search['optimizerFtol']:g}.",'',
      'Active numerical/domain bounds: '+('; '.join(hits) if hits else 'none detected')+'.','',
      '## Candidate dimensions','',
      '| Quantity | Search result |','|---|---:|',
      f"| Wing area | {d['sail_m2']:.3f} m² |",
      f"| Wing span / chord | {(d['sail_m2']*d['sail_AR'])**.5:.3f} / {(d['sail_m2']/d['sail_AR'])**.5:.3f} m |",
      f"| Wing aspect ratio | {d['sail_AR']:.3f} |",
      f"| Camber / thickness scale relative to CAD section | {d['camber_scale']:.3f} / {d['wing_thickness_scale']:.3f} |",
      f"| Keel area / span | {d['keel_m2']:.3f} m² / {d['keel_span_m']:.3f} m |",
      f"| Rudder area / span | {d['rudder_m2']:.4f} m² / {d['rudder_span_m']:.3f} m |",
      f"| Ballast | {d['ballast_kg']:.2f} kg |",
      f"| Battery / solar panel | {d['battery_Wh']:.1f} Wh / {d['panel_m2']:.3f} m² |",'',
      'These continuous variables describe the analysis geometry, not production dimensions or selected commercial hardware. See the linked search data for laminate, rib spacing, placement and drive ratings.','',
      '## What the coupled calculation changes','',
      'The wing uses its CAD section for skin mass, weak-axis stiffness and displaced volume. Finite-thickness laminate section properties replace the thin-wall approximation, which could overpredict even solid-section stiffness at high material packing. Both chord orientations supply VSPAERO polars; wing moment affects yaw balance and actuator demand. Motor/gearbox moving losses are separate from holding/controller loads. Tack time fractions cancel crosswind displacement before current and route duration are evaluated.','',
      'The old reference wing passes its bending-strength screen but fails the declared tip-deflection allocation with the CAD section. Its generic section approximation was insufficient. The free-design search can adjust area, aspect ratio, thickness, laminate, ballast and actuator ratings together.','',
      '## Candidate aerodynamic interpolation check','',
      'Direct VSPAERO runs at the candidate aspect ratio and camber are compared with the saved grid at all eight incidence nodes. Both use the grid’s reference thickness and mesh 24. The differences below are coefficient errors, not physical validation.','',
      '| Chord orientation | Maximum absolute CL difference | Maximum absolute CDi difference | Maximum absolute CMy difference |',
      '|---|---:|---:|---:|',
      *[f"| {'Reversed' if c['reverseChord'] else 'Original'} | {c['maxAbsoluteInterpolationError']['CLtot']:.5f} | {c['maxAbsoluteInterpolationError']['CDi']:.5f} | {c['maxAbsoluteInterpolationError']['CMytot']:.5f} |" for c in wing['cases']], '',
      'The optimized thickness change is used by mass, stiffness and buoyancy calculations; its viscous aerodynamic effect is not established by this thin-wing calculation. [Direct comparison data](analysis/wing-candidate-check.json).','',
      '## Refined replay and sensitivities','',
      'Replay uses finer geometry, re-solves both-tack operating states, and evaluates four mast positions through -180 to 180 degrees with hydrostatic heave and pitch equilibrium. Selected screens include signed roll moments along the chosen pitch-equilibrium branch. A positive roll moment on a pitch-unstable branch does not prove a recoverable trajectory. Missing equilibria within the ±85° pitch search range remain unresolved and prevent the recovery screen from passing; they are not proof of physical impossibility. Dynamic recovery remains unverified.','',
      '| Scenario | Operating / practical screens pass | Sampled roll screen pass | Lowest operating margin | Lowest structural/practical margin | Route time E / W (h) | Missing pitch equilibria | Pitch-unstable samples |','|---|---|---|---:|---:|---:|---:|---:|']
    for r in replay['scenarios']:
        duration=f"{r['route'][5]:.2f} / {r['westerlyRoute'][5]:.2f}" if all(c['screenFeasible'] for c in r['cases']) and r['route'][5]<1e5 else 'Not established'
        lines.append(f"| {r['scenario']} | {core_pass(r)} | {roll_pass(r)} | {margin(r['minimumOperatingMargin'])} | {margin(min(r['structure'].values()))} | {duration} | {sum(curve['failedEquilibria'] for curve in r['recovery'])} | {sum(not p.get('pitch_stable',False) for curve in r['recovery'] for p in curve['points'] if 'failure' not in p)} |")
    from .native_hull_resistance import NAMES
    labels={f'delftDomain{i}':'Delft '+name for i,name in enumerate(NAMES[3:],4)}
    lines+=['','Governing failures by scenario (normalized margins):','']
    for r in replay['scenarios']:
        operating_names=contract['outputNames'][4:18]+contract['outputNames'][47:]
        failures={n:min(c['outputs'][n] for c in r['cases']) for n in operating_names}
        failures.update(r['structure'])
        failures.update(zip(['easterlyDownstreamProgress','easterlyUpstreamProgress','easterlyDuration'],r['route'][:3]))
        failures.update(zip(['westerlyDownstreamProgress','westerlyUpstreamProgress','westerlyDuration'],r['westerlyRoute'][:3]))
        failed=sorted(((n,v) for n,v in failures.items() if v < -1e-4),key=lambda item:item[1])
        description='; '.join(f'{labels.get(n,n)}: {v:.3f}' for n,v in failed[:5]) or 'No failed operating, structural or route margins.'
        diagnostics=sum(not c['energyConstraintsEnforced'] for c in r['cases'])
        if diagnostics:description=description.rstrip('.')+f'. {diagnostics}/8 cases use energy-unconstrained diagnostic controls after a failed constrained attempt.'
        if not r['numericallyBalanced']:description+=' Some operating states did not meet equilibrium tolerance.'
        lines.append(f"- **{r['scenario']}**: {description}")
    lines+=['',
      'Normalized margins below -0.0001 fail the selected screen; smaller numerical residuals display as zero. Scenario brackets are engineering sensitivities, not measured distributions or guaranteed worst-case bounds. Operating controls are first optimized with energy constraints enforced. A failed constrained attempt gets a labelled energy-unconstrained diagnostic to expose the remaining performance and energy deficit; all margins are still checked afterward. These local attempts do not prove that every possible control policy is infeasible. Controls are reoptimized for each scenario; local solutions and coupled load changes can produce non-monotonic route times: see [native inputs](../models/coupled-uncertainty.sysml). Route times are shown only when every operating case passes the non-energy operating and model-domain screens. E / W denotes easterly / westerly wind: upstream is windward for an easterly, leeward for a westerly. Both profiles use 100 km per leg, equal-time 5/8 m/s wind cases, and the declared downstream currents. They use synthetic wind/current exposure and rigid geometry; no accepted-weather or ocean qualification is implied.','',
      '## Water-ingress recovery sensitivities','',
      '| Wing state | Cases with positive sampled roll moments | Worst restoring moment (Nm) | Missing pitch equilibria | Pitch-unstable samples |','|---|---:|---:|---:|---:|']
    for state in ['sealed','free_flooding_homogenized','full_water_retention']:
        cases=[c for c in recovery['cases'] if c['wing_state']==state]
        lines.append(f"| {state} | {sum(c['sampledInteriorRestores'] for c in cases)}/{len(cases)} | {min(c['minimumInteriorRestoring_Nm'] for c in cases if c['minimumInteriorRestoring_Nm'] is not None):.2f} | {sum(c['failedEquilibria'] for c in cases)} | {sum(not p.get('pitch_stable',False) for c in cases for p in c['points'] if 'failure' not in p)} |")
    lines+=['',
      'Each state covers freshwater and seawater at four locked mast positions. Free flooding uses homogenized material buoyancy; full retention fills the estimated void at its volume centroid. These are static loading sensitivities, not predictions of leakage, drainage or slosh. See [recovery data](analysis/coupled-recovery.json).','',
      '![Static recovery curves with pitch instability and missing solutions marked](figures/coupled-recovery.svg)','',
      '## Missing-pitch-equilibrium diagnostic','',
      'The original recovery sweep brackets pitch from −85° to +85°. A supplemental full-range search checks each missing sealed-wing sample using 2.5° brackets. This distinguishes a search-range limitation from absence of static equilibrium; neither search proves a dynamic recovery path.','',
      '| Water density (kg/m³) | Mast trim (deg) | Roll (deg) | Pitch roots (deg; local pitch stability) |',
      '|---:|---:|---:|---|',
      *[f"| {c['density_kg_m3']:g} | {c['mast_trim_deg']:g} | {c['heel_deg']:g} | "+'; '.join(f"{r['pitch_deg']:.3f} ({'stable' if r['pitch_stable'] else 'unstable'})" for r in c['roots'])+' |' for c in pitch['cases']], '',
      'Local pitch stability is not full three-dimensional stability. The original replay verdicts retain their declared search range; this diagnostic does not silently convert them into recovery passes. [Full diagnostic data](analysis/coupled-pitch-diagnostic.json).','',
      '## Decision','',
      f"Nominal operating/practical screens pass: **{core_pass(nominal)}**. Nominal sampled roll screen passes: **{roll_pass(nominal)}**. These are separate from physical mission verification.",'',
      'Use the replay verdicts to decide whether further sizing is justified. A failed nominal replay invalidates the coarse candidate; failed adverse cases identify design margins or evidence that still need resolution. Active numerical bounds require investigation before a minimum-size claim.','',
      'The [hull-resistance report](hull-resistance.md) documents the regression, geometry screening and verification. The separate hydrodynamic sensitivity increases residuary resistance by 30%; the combined case includes that increase. These brackets do not substitute for hull-specific tow evidence.','',
      'Remaining evidence includes viscous/stall and broadside wing behavior, aerodynamic thickness sensitivity, hull-form resistance, environmental/fouling exposure, selected hardware and its packaging/CG, laminate/joint properties, ingress/drainage behavior and dynamic recovery. These are separate from numerical solver convergence.','',
      '[Search data](analysis/coupled-sizing-search.json) · [Refined replay](analysis/coupled-sizing-replay.json) · [Reference operating cases](analysis/coupled-fixed-design.json) · [Method and requirement coverage](coupled-sizing.md)','']
    wh=lambda value:f'{0.0 if abs(value)<.0005 else value:.3f}'
    energy_lines=['## Mass and energy at the same geometry','','| Scenario | Replay mass (kg) | Average-power range (W) | Minimum cycle balance (Wh) | Minimum overnight reserve margin (Wh) |','|---|---:|---:|---:|---:|']
    for r in replay['scenarios']:
        values=[c['outputs'] for c in r['cases']]
        energy_lines.append(f"| {r['scenario']} | {values[0]['mass_kg']:.2f} | {min(v['averagePower'] for v in values):.2f}–{max(v['averagePower'] for v in values):.2f} | {wh(min(v['cycleEnergy'] for v in values))} | {wh(min(v['reserveMargin'] for v in values))} |")
    energy_lines+=['','These are separate minima across eight steady operating cases at the same vessel geometry. Energy-screen acceptance uses a 0.01 Wh numerical tolerance, which is separate from engineering reserve; route-level weather and duty-cycle histories remain a separate validation task. Diagnostic-control cases are identified above.','']
    lines[lines.index('## Water-ingress recovery sensitivities'):lines.index('## Water-ingress recovery sensitivities')]=energy_lines
    if not pitch['cases']:
        start=lines.index('## Missing-pitch-equilibrium diagnostic')
        end=lines.index('## Decision')
        lines[start:end]=['## Pitch-equilibrium coverage','','All recovery samples found a pitch equilibrium within the declared search range. This does not establish pitch stability or a dynamic recovery trajectory. [Diagnostic data](analysis/coupled-pitch-diagnostic.json).','']
    return '\n'.join(lines)

if __name__=='__main__':
    from .plot_coupled_recovery import render
    render()
    (ROOT/'docs/coupled-results.md').write_text(publication(),encoding='utf-8')
